from pathlib import Path
import os
ignored=Path('../../tests/test-lists/ets-cts/ets-cts-ignored.txt')
base=Path(os.environ['PI_TEST_DIR'])
entries=[]
for line in ignored.read_text().splitlines():
    s=line.strip()
    if not s or s.startswith('#'): continue
    if s.startswith('15.semantic_rules/09.overriding/'):
        entries.append(s)
roots=['ets-cts','ets-cts-7.0']
for e in entries:
    found=[]
    variants=[e, e.replace('15.semantic_rules/09.overriding/','15.semantic_rules/08.overriding/')]
    for suite in roots:
      for stage in ['gen','intermediate']:
        for v in variants:
          p=base/suite/stage/v
          if p.exists(): found.append(str(p))
    print(f"{e}\n  " + "\n  ".join(found or ['MISSING']))
