    ETSObjectType *declaringType;     // generic declaration owner, e.g. I<T>
    ETSObjectType *instantiatedType;  // view along this path, e.g. I<string>
    SubstitutionMap substitution;
};

// May be methods on SemanticRelations rather than a separate class.
SupertypeView ViewOfSupertype(ETSObjectType *rootType, ETSObjectType *declaringType);

Signature *ViewSignatureFrom(const SupertypeView &view, Signature *originalSignature);
